define(["jquery", "Magento_Ui/js/modal/modal"], function($, modal) {
    $('.registercomplaintpopupmodal').on('click', function() {
        console.log("calling ....");
        var options = {
            type: 'popup',
            responsive: true,
            innerScroll: true,
            title: 'Register Complaint',
            buttons: false
        };
        var popup = modal(options, $('#modal-register-complaint'));
        $("#modal-register-complaint").modal("openModal");
    });
});